-- 0230 — Academy, niveau 4 réécrit et renommé (2026-11-14).
--
-- « Niveau 4 — Expert CREPMF » portait le nom d'une autorité remplacée par
-- l'AMF-UMOA le 1er octobre 2022 (Traité révisé de l'UMOA du 12/07/2019), et
-- citait des « articles 1 à 6 » invérifiables. Il devient « Niveau 4 — Expert :
-- régulation et marché primaire », cinq leçons : architecture du marché,
-- information et intégrité, compartiments et indices (communiqué BRVM du
-- 02/01/2023 : Prestige = 10 ans, 50 Md FCFA, flottant 20 % et 4 M de titres),
-- pourquoi entrer en bourse (cas BBGC, 24/09/2026), procédure d'introduction.
-- Aucun numéro d'article cité ; avertissement « seuls les textes officiels font foi ».
-- Source : frontend/lib/academy/contenus/niveau4/*.json (testés).
-- Sauvegarde : docs/academy/sauvegardes/2026-11-14-academy-niveau-4-expert.json
-- À appliquer APRÈS le déploiement (codes d'indices BRVMPRES/BRVMPRIN).
-- Progression remappée (2→3, 3→4) ; aucun élève au 2026-11-14.
-- refonte_majeure_le n'est PAS modifiée (elle pilote des droits d'accès).

do $do$
declare
  v_id uuid;
begin
  select id into v_id from public.academy_courses
   where slug = 'academy-niveau-4-expert'
     and jsonb_array_length(content->'lessons') = 4;
  if v_id is null then
    raise notice '0230 : cours déjà réécrit (ou introuvable), rien à faire';
    return;
  end if;

  -- Progression indexée par position : chaque ancienne leçon garde son élève.
  update public.academy_progress
     set lesson_idx = case lesson_idx when 2 then 3 when 3 then 4 else lesson_idx end
   where course_id = v_id;

  update public.academy_courses
     set content = jsonb_set(jsonb_set(jsonb_set(content, '{lessons}', $wb$[{"titre": "Leçon 1 — L’architecture du marché financier régional", "module": "Module 1 — Régulation et intégrité du marché", "categorie": "regulatory", "duree_min": 11, "sous_titre": "Qui réglemente, qui organise, qui conserve, qui négocie : les institutions du marché de l’UMOA et leurs rôles.", "resume": "Le marché financier régional de l’UMOA repose sur quelques institutions aux rôles distincts. L’AMF-UMOA, qui a succédé au CREPMF, réglemente et contrôle ; la BRVM organise la cotation ; le Dépositaire central conserve les titres et règle les transactions ; les SGI sont les seules à pouvoir négocier en bourse. Cette leçon décrit chacun de ces rôles et ce qu’ils changent pour l’investisseur.", "sections": [{"type": "definition", "titre": "Les institutions et leurs rôles", "contenu": "Chaque acteur a un périmètre précis. Savoir qui fait quoi permet de savoir à qui s’adresser.", "tableau": {"colonnes": ["Institution", "Rôle", "Ce que cela signifie pour vous"], "lignes": [["AMF-UMOA", "Autorité de régulation : agrément des acteurs, visa des opérations, contrôle et sanctions", "C’est elle qui protège l’épargne publique et qui reçoit les réclamations"], ["BRVM", "Entreprise de marché : admission à la cote, cotation, diffusion des cours", "Elle publie les cours, le Bulletin officiel de la cote et les avis"], ["Dépositaire central / Banque de règlement", "Conservation centrale des titres, règlement et livraison des transactions", "Il garantit que vos titres existent et changent bien de main"], ["SGI", "Sociétés de gestion et d’intermédiation agréées : seules habilitées à négocier en bourse", "Tout ordre passe par une SGI ; elle tient souvent votre compte-titres"], ["Sociétés de gestion d’OPCVM", "Gestion des fonds collectifs", "Elles gèrent les FCP et SICAV que vous pouvez souscrire"]], "note": "Les banques, elles, sont supervisées par la Commission bancaire de l’UMOA, aux côtés de la BCEAO."}}, {"type": "importance", "titre": "Du CREPMF à l’AMF-UMOA", "contenu": "Le Conseil régional de l’épargne publique et des marchés financiers (CREPMF) a été transformé en Autorité des marchés financiers de l’UMOA (AMF-UMOA). Le changement résulte du Traité révisé de l’UMOA du 12 juillet 2019, entré en vigueur le 1er octobre 2022.\nLa réforme a notamment doté l’autorité d’une Commission des sanctions et d’un Médiateur.", "etapes": [{"titre": "12 juillet 2019", "detail": "Signature du Traité révisé de l’UMOA."}, {"titre": "1er octobre 2022", "detail": "Entrée en vigueur : l’AMF-UMOA a succédé au CREPMF.", "cle": true}, {"titre": "Depuis", "detail": "L’AMF-UMOA agrée, contrôle et sanctionne ; une Commission des sanctions statue sur les manquements."}], "etapes_style": "frise"}, {"type": "importance", "titre": "Le circuit d’un ordre de bourse", "contenu": "Un achat d’actions traverse plusieurs institutions avant que les titres n’arrivent sur votre compte.", "flux": [{"titre": "Vous", "detail": "Transmettez un ordre à votre SGI", "icone": "actionnaires"}, {"titre": "SGI", "detail": "Place l’ordre sur le système de cotation", "icone": "entreprise"}, {"titre": "BRVM", "detail": "Rapproche acheteurs et vendeurs", "icone": "graphique"}, {"titre": "Dépositaire central", "detail": "Règle l’argent et livre les titres", "icone": "paiement"}, {"titre": "Compte-titres", "detail": "Les actions sont inscrites à votre nom", "icone": "piece"}]}, {"type": "piege", "titre": "Les confusions fréquentes", "contenu": "Des erreurs de compréhension qui coûtent cher en cas de litige.", "points": [{"titre": "Croire que la BRVM garantit les sociétés", "detail": "La BRVM organise la cotation ; elle ne garantit ni la solidité des sociétés ni le cours.", "verifier": "Les comptes publiés par la société."}, {"titre": "Passer par un intermédiaire non agréé", "detail": "Seule une SGI agréée peut négocier en bourse. Un « placement » proposé hors de ce circuit n’offre pas les mêmes protections.", "verifier": "La liste des acteurs agréés publiée par l’AMF-UMOA."}, {"titre": "S’étonner de l’ancien nom", "detail": "Les documents antérieurs à octobre 2022 parlent de l’ex-CREPMF : il s’agit de la même autorité, sous son ancien nom.", "verifier": "La date du document."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Quatre acteurs, quatre rôles.", "points": [{"titre": "L’AMF-UMOA réglemente, agrée, contrôle et sanctionne"}, {"titre": "La BRVM organise la cotation et publie les cours"}, {"titre": "Le Dépositaire central conserve les titres et règle les transactions"}, {"titre": "Seule une SGI agréée peut négocier vos ordres"}]}], "quiz": [{"question": "Quelle institution a succédé à l’ex-CREPMF ?", "options": ["La BCEAO", "L’AMF-UMOA", "La BRVM", "La Commission bancaire"], "correct": 1, "explication": "L’AMF-UMOA a succédé au CREPMF le 1er octobre 2022, à l’entrée en vigueur du Traité révisé de l’UMOA."}, {"question": "Qui est seul habilité à négocier vos ordres en bourse ?", "options": ["Votre banque, quelle qu’elle soit", "Une SGI agréée", "La BRVM directement", "Le Dépositaire central"], "correct": 1, "explication": "Les ordres de bourse passent obligatoirement par une SGI agréée."}, {"question": "Quel est le rôle du Dépositaire central / Banque de règlement ?", "options": ["Fixer les cours", "Conserver les titres et régler les transactions", "Agréer les SGI", "Publier les comptes des sociétés"], "correct": 1, "explication": "Il assure la conservation centrale des titres, le règlement et la livraison."}, {"question": "La BRVM garantit-elle la solidité des sociétés cotées ?", "options": ["Oui, toujours", "Non : elle organise la cotation, sans garantir les sociétés ni les cours", "Oui, pour le compartiment Prestige", "Seulement pour les banques"], "correct": 1, "explication": "La cotation n’est pas une garantie : l’investisseur reste exposé au risque de la société."}, {"question": "Quel organe la réforme de 2022 a-t-elle créé au sein de l’AMF-UMOA ?", "options": ["Une banque centrale", "Une Commission des sanctions", "Une nouvelle bourse", "Un fonds de garantie des dépôts"], "correct": 1, "explication": "La réforme a doté l’AMF-UMOA d’une Commission des sanctions et d’un Médiateur."}], "liens": [{"label": "Choisir sa SGI", "href": "/comparateur-sgi"}, {"label": "Les sociétés cotées", "href": "/societes"}, {"label": "La qualité de nos données", "href": "/qualite-donnees"}], "avertissement": "Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.", "charts": [], "qcm": {"question": "Quelle institution a succédé à l’ex-CREPMF ?", "options": ["La BCEAO", "L’AMF-UMOA", "La BRVM", "La Commission bancaire"], "correct": 1, "explication": "L’AMF-UMOA a succédé au CREPMF le 1er octobre 2022, à l’entrée en vigueur du Traité révisé de l’UMOA."}}, {"titre": "Leçon 2 — L’information et l’intégrité du marché", "module": "Module 1 — Régulation et intégrité du marché", "categorie": "regulatory", "duree_min": 11, "sous_titre": "Ce que les sociétés doivent publier, ce qu’est une information privilégiée, et les abus que la réglementation sanctionne.", "resume": "Un marché ne fonctionne que si tous les investisseurs disposent de la même information au même moment. Les sociétés cotées ont donc des obligations de publication, périodiques et permanentes, et l’usage d’une information privilégiée est interdit. Cette leçon décrit ces obligations, les principaux abus de marché et les réflexes à adopter.", "sections": [{"type": "definition", "titre": "Deux obligations d’information", "contenu": "Une société cotée informe le marché selon un calendrier, et chaque fois qu’un fait important survient.", "points": [{"titre": "L’information périodique", "detail": "États financiers annuels certifiés, rapports d’activité trimestriels et semestriels, publiés dans des délais fixés."}, {"titre": "L’information permanente", "detail": "Tout fait nouveau susceptible d’influencer sensiblement le cours doit être rendu public sans délai : résultat inattendu, contrat majeur, litige, changement de dirigeant."}]}, {"type": "importance", "titre": "L’information privilégiée", "contenu": "Une information est dite privilégiée quand elle réunit trois caractères. Celui qui la détient ne doit ni s’en servir pour opérer, ni la communiquer, tant qu’elle n’est pas publique.", "points": [{"titre": "Précise", "detail": "Elle porte sur un fait ou un événement déterminé, pas sur une rumeur vague."}, {"titre": "Non publique", "detail": "Elle n’a pas encore été diffusée au marché par les canaux officiels."}, {"titre": "Susceptible d’influencer le cours", "detail": "Un investisseur raisonnable en tiendrait compte pour décider."}]}, {"type": "cas", "titre": "Les principaux abus de marché", "contenu": "Les comportements visés par la réglementation, résumés à titre pédagogique.", "tableau": {"colonnes": ["Abus", "En quoi il consiste", "Exemple pédagogique"], "lignes": [["Délit d’initié", "Opérer ou faire opérer grâce à une information privilégiée", "Un salarié achète avant l’annonce d’un résultat exceptionnel"], ["Communication illicite", "Transmettre une information privilégiée hors du cadre de ses fonctions", "Un conseiller confie l’annonce à venir à un proche"], ["Manipulation de cours", "Passer des ordres pour fixer artificiellement un cours", "Des achats répétés en fin de séance pour gonfler la clôture"], ["Fausse information", "Diffuser une information trompeuse pour influencer le cours", "Une rumeur inventée de rachat publiée sur les réseaux"]], "note": "L’AMF-UMOA enquête et sanctionne ; des poursuites pénales relèvent des législations nationales."}}, {"type": "importance", "titre": "Pourquoi cela concerne aussi le petit investisseur", "contenu": "Les abus de marché ne sont pas réservés aux initiés. Relayer une rumeur de rachat dans un groupe de discussion, ou acheter sur la foi d’un « tuyau » venu de l’intérieur d’une société, expose à des risques réels.\nSur un marché peu liquide, quelques ordres suffisent à déplacer un cours : la vigilance y est d’autant plus nécessaire."}, {"type": "piege", "titre": "Les bons réflexes", "contenu": "Quelques règles simples protègent votre épargne et votre responsabilité.", "points": [{"titre": "Se fier aux publications officielles", "detail": "Les avis de la BRVM et les communiqués des sociétés font foi, pas les rumeurs.", "verifier": "La source et la date de l’information."}, {"titre": "Se méfier des « tuyaux »", "detail": "Une information présentée comme confidentielle et sûre est soit fausse, soit interdite d’usage.", "verifier": "Si elle est publique."}, {"titre": "Signaler un abus", "detail": "Un comportement suspect peut être signalé à l’AMF-UMOA.", "verifier": "Les canaux de réclamation de l’AMF-UMOA."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Même information, au même moment, pour tous.", "points": [{"titre": "Information périodique et permanente : deux obligations des sociétés cotées"}, {"titre": "Information privilégiée : précise, non publique, et pouvant influencer le cours"}, {"titre": "Délit d’initié, manipulation, fausse information : des abus sanctionnés"}, {"titre": "Ne décider que sur des informations publiques et officielles"}]}], "quiz": [{"question": "Quels sont les trois caractères d’une information privilégiée ?", "options": ["Ancienne, publique, sans effet", "Précise, non publique, susceptible d’influencer le cours", "Vague, publique, chiffrée", "Officielle, ancienne, confidentielle"], "correct": 1, "explication": "Une information privilégiée est précise, non encore publique, et susceptible d’influencer sensiblement le cours."}, {"question": "Une société signe un contrat majeur. Que lui impose l’information permanente ?", "options": ["D’attendre le rapport annuel", "De le rendre public sans délai s’il peut influencer le cours", "De n’en parler qu’aux grands actionnaires", "Rien"], "correct": 1, "explication": "Tout fait susceptible d’influencer sensiblement le cours doit être publié sans délai."}, {"question": "Des achats répétés en fin de séance pour gonfler le cours de clôture relèvent :", "options": ["D’une stratégie normale", "De la manipulation de cours", "D’une information périodique", "D’un dividende"], "correct": 1, "explication": "Fixer artificiellement un cours par ses ordres est une manipulation."}, {"question": "Un ami salarié d’une société cotée vous annonce un excellent résultat, pas encore publié. Que faire ?", "options": ["Acheter avant l’annonce", "Ne pas opérer sur cette base : l’information est privilégiée", "La relayer à d’autres", "Vendre à découvert"], "correct": 1, "explication": "Utiliser ou transmettre une information privilégiée est interdit, pour lui comme pour vous."}, {"question": "Qui enquête et sanctionne les abus de marché dans l’UMOA ?", "options": ["La BRVM seule", "L’AMF-UMOA", "Chaque SGI", "Personne"], "correct": 1, "explication": "L’AMF-UMOA enquête et sanctionne ; des poursuites pénales relèvent des législations nationales."}], "liens": [{"label": "Les sociétés cotées", "href": "/societes"}, {"label": "Les opérations sur titres", "href": "/operations-titres"}, {"label": "La qualité de nos données", "href": "/qualite-donnees"}], "avertissement": "Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.", "charts": [], "qcm": {"question": "Quels sont les trois caractères d’une information privilégiée ?", "options": ["Ancienne, publique, sans effet", "Précise, non publique, susceptible d’influencer le cours", "Vague, publique, chiffrée", "Officielle, ancienne, confidentielle"], "correct": 1, "explication": "Une information privilégiée est précise, non encore publique, et susceptible d’influencer sensiblement le cours."}}, {"titre": "Leçon 3 — Les compartiments et les indices de la BRVM", "module": "Module 2 — Marché primaire et introduction en bourse", "categorie": "general", "duree_min": 9, "sous_titre": "Prestige, Principal, Croissance : comment la BRVM classe ses valeurs depuis 2023, et ce que mesurent ses indices.", "resume": "Depuis le 2 janvier 2023, le marché des actions de la BRVM est organisé en trois compartiments : Prestige, Principal et Croissance. Les critères tiennent à l’ancienneté, à la taille, au flottant et à la qualité de l’information. De nouveaux indices sont nés en même temps. Cette leçon explique ces classements et ce qu’on peut en lire.", "sections": [{"type": "definition", "titre": "Trois compartiments", "contenu": "La réorganisation est entrée en vigueur le 2 janvier 2023, selon le communiqué publié par la BRVM ce jour-là.", "tableau": {"colonnes": ["Compartiment", "Pour qui", "Critères publiés"], "lignes": [["Prestige", "Les grandes sociétés établies", "10 ans d’activité, 50 Md FCFA de capitalisation, flottant d’au moins 20 % et 4 millions de titres, information régulière, engagement RSE"], ["Principal", "Les sociétés cotées qui ne relèvent pas du Prestige", "Les critères d’admission généraux de la BRVM"], ["Croissance", "Les PME et les entreprises à fort potentiel de croissance", "Des conditions d’accès allégées, avec un accompagnement spécifique"]], "note": "Source : communiqué de la BRVM du 2 janvier 2023. Le règlement de la BRVM fait foi pour le détail des critères."}}, {"type": "importance", "titre": "Les indices de la BRVM", "contenu": "Un indice résume l’évolution d’un groupe de valeurs. Depuis 2023, la BRVM publie notamment trois indices de référence.", "points": [{"titre": "BRVM Composite", "detail": "Toutes les sociétés cotées, pondérées par leur capitalisation."}, {"titre": "BRVM 30", "detail": "Les trente valeurs les plus échangées sur un trimestre ; il a remplacé le BRVM 10."}, {"titre": "BRVM Prestige", "detail": "Les valeurs du compartiment Prestige ; sa composition est révisée chaque année."}]}, {"type": "cas", "titre": "Sur la BRVM : les indices à la dernière séance", "reel": true, "contenu": "Les valeurs des principaux indices, lues en base à l’ouverture de la leçon.", "donnees_reelles": {"vue": "indices", "codes": ["BRVMC", "BRVM30", "BRVMPRES", "BRVMPRIN"]}}, {"type": "piege", "titre": "Ce qu’un compartiment ne dit pas", "contenu": "Un classement décrit des caractéristiques, pas une qualité d’investissement.", "points": [{"titre": "Prestige ne veut pas dire « sans risque »", "detail": "Une grande société peut voir ses résultats baisser et son cours reculer.", "verifier": "Les comptes et la valorisation de la société."}, {"titre": "Croissance ne veut pas dire « croissance assurée »", "detail": "Le compartiment accueille des entreprises jeunes, souvent plus risquées et moins liquides.", "verifier": "La liquidité et l’historique de la valeur."}, {"titre": "Un indice pondéré par la capitalisation est concentré", "detail": "Quelques grandes valeurs y pèsent lourd.", "verifier": "Le poids des premières valeurs dans l’indice."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Classer n’est pas recommander.", "points": [{"titre": "Trois compartiments depuis le 2 janvier 2023 : Prestige, Principal, Croissance"}, {"titre": "Prestige : 10 ans, 50 Md FCFA de capitalisation, 20 % de flottant"}, {"titre": "BRVM Composite, BRVM 30, BRVM Prestige : trois indices de référence"}, {"titre": "Un compartiment décrit une société, il ne juge pas son action"}]}], "quiz": [{"question": "Depuis quand le marché des actions de la BRVM est-il organisé en compartiments Prestige, Principal et Croissance ?", "options": ["1998", "2 janvier 2023", "1er octobre 2022", "2026"], "correct": 1, "explication": "La réorganisation est entrée en vigueur le 2 janvier 2023."}, {"question": "Quel flottant minimum le compartiment Prestige exige-t-il ?", "options": ["5 % du capital", "20 % du capital, et au moins 4 millions de titres", "50 % du capital", "Aucun"], "correct": 1, "explication": "Le communiqué de la BRVM fixe un flottant d’au moins 20 % du capital, correspondant à au moins 4 millions de titres."}, {"question": "Que regroupe l’indice BRVM 30 ?", "options": ["Les 30 plus grandes capitalisations", "Les 30 valeurs les plus échangées sur un trimestre", "Les 30 plus anciennes sociétés", "30 obligations"], "correct": 1, "explication": "Le BRVM 30 regroupe les trente valeurs les plus échangées sur un trimestre."}, {"question": "À qui s’adresse le compartiment Croissance ?", "options": ["Aux banques uniquement", "Aux PME et aux entreprises à fort potentiel de croissance", "Aux États", "Aux OPCVM"], "correct": 1, "explication": "Le compartiment Croissance est destiné aux PME et aux entreprises à fort potentiel de croissance."}, {"question": "Une société du compartiment Prestige est-elle un placement sans risque ?", "options": ["Oui", "Non : le compartiment décrit sa taille et sa transparence, pas l’évolution de son cours", "Oui, si elle verse un dividende", "Oui, pendant 10 ans"], "correct": 1, "explication": "Le classement repose sur des critères de taille, de flottant et d’information, pas sur une garantie de performance."}], "liens": [{"label": "Les secteurs et les indices", "href": "/secteurs"}, {"label": "Les sociétés cotées", "href": "/societes"}, {"label": "La liquidité de chaque valeur", "href": "/liquidite"}], "avertissement": "Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.", "charts": [], "qcm": {"question": "Depuis quand le marché des actions de la BRVM est-il organisé en compartiments Prestige, Principal et Croissance ?", "options": ["1998", "2 janvier 2023", "1er octobre 2022", "2026"], "correct": 1, "explication": "La réorganisation est entrée en vigueur le 2 janvier 2023."}}, {"titre": "Leçon 4 — Pourquoi une société entre en bourse", "module": "Module 2 — Marché primaire et introduction en bourse", "categorie": "fundamental", "duree_min": 10, "sous_titre": "Lever des fonds, donner une valeur à l’entreprise, permettre à des actionnaires de sortir : les raisons, les coûts et les contraintes.", "resume": "Une introduction en bourse permet à une société de lever des capitaux ou à ses actionnaires de céder une partie de leurs titres au public. Elle apporte de la visibilité et une valeur de marché, mais impose transparence, coûts et contraintes durables. Cette leçon présente ces arbitrages, avec l’exemple de l’admission la plus récente à la BRVM.", "sections": [{"type": "definition", "titre": "Deux façons d’entrer en bourse", "contenu": "Ce qui est vendu au public détermine à qui va l’argent.", "tableau": {"colonnes": ["Opération", "Ce qui est vendu", "À qui va l’argent"], "lignes": [["Augmentation de capital", "Des actions nouvelles", "À la société, qui peut investir"], ["Offre publique de vente (OPV)", "Des actions existantes", "Aux actionnaires qui cèdent leurs titres"], ["Opération mixte", "Les deux à la fois", "En partie à la société, en partie aux vendeurs"]], "note": "Lire la note d’information pour savoir qui reçoit l’argent levé : c’est une indication sur le projet."}}, {"type": "importance", "titre": "Ce que la société gagne, ce qu’elle accepte", "contenu": "L’introduction est un arbitrage durable, pas un événement d’un jour.", "points": [{"titre": "Gains", "detail": "Accès à l’épargne du public, valeur de marché quotidienne, notoriété, possibilité de lever à nouveau des fonds plus tard."}, {"titre": "Contraintes", "detail": "Publication régulière des comptes et des faits importants, contrôle de l’AMF-UMOA, assemblées ouvertes à de nombreux actionnaires."}, {"titre": "Coûts", "detail": "Rémunération des conseils et de la SGI chef de file, frais d’admission et de cotation, coûts de communication financière."}]}, {"type": "cas", "titre": "Un exemple récent : Bridge Bank Group Côte d’Ivoire", "contenu": "Bridge Bank Group Côte d’Ivoire (code BBGC) est devenue la 48e société cotée de la BRVM, avec une première cotation le 24 septembre 2026. L